   724                  ((uint64_t)up[4]<<24) |
   725                  ((uint64_t)up[5]<<16) |
   726                  ((uint64_t)up[6]<< 8) |
   727                   (uint64_t)up[7]) & ((1LL<<(7*8))-1);
   728      } else {
